import random
import string
from typing import List

# This generator produces UTF-8 byte sequences intended to be consumed by FUZZ_PARAM_STR
# in the provided ImPlot fuzzing stubs. Strings are used for titles, labels, legend
# entries, etc. We focus on generating: unique-ish IDs, visible titles, empty/hidden
# labels (using ## to hide), long strings, numeric-like strings for tick labels, and
# mixed unicode. We keep output under 4096 bytes.

UNICODE_BLOCKS = [
    # A few ranges with varied width/combining behavior
    (0x0020, 0x007E),   # Basic Latin (printable ASCII)
    (0x00A0, 0x00FF),   # Latin-1 Supplement
    (0x0300, 0x036F),   # Combining Diacritical Marks
    (0x0370, 0x03FF),   # Greek and Coptic
    (0x0400, 0x04FF),   # Cyrillic
    (0x2000, 0x206F),   # General Punctuation (various spaces)
    (0x2070, 0x209F),   # Superscripts and Subscripts
    (0x2190, 0x21FF),   # Arrows
    (0x2460, 0x24FF),   # Enclosed Alphanumerics
    (0x2500, 0x257F),   # Box Drawing
    (0x2580, 0x259F),   # Block Elements
    (0x25A0, 0x25FF),   # Geometric Shapes
    (0x2600, 0x26FF),   # Miscellaneous Symbols
    (0x1F300, 0x1F5FF), # Misc Symbols and Pictographs (emoji)
]

def _rand_unicode_char(rng: random.Random) -> str:
    # Prefer printable ASCII often, but occasionally pick from other blocks
    if rng.random() < 0.6:
        return chr(rng.randint(0x20, 0x7E))
    block = rng.choice(UNICODE_BLOCKS)
    cp = rng.randint(block[0], block[1])
    try:
        ch = chr(cp)
        # Avoid surrogate range and control chars
        if 0xD800 <= cp <= 0xDFFF or (cp < 0x20 and cp not in (0x09, 0x0A, 0x0D)):
            return ' '
        return ch
    except ValueError:
        return ' '

def _rand_visible_string(rng: random.Random, length: int) -> str:
    return ''.join(_rand_unicode_char(rng) for _ in range(length))

def _hidden_label(rng: random.Random) -> str:
    # ImGui/ImPlot convention: "Visible##ID" => shows Visible, uses ID for uniqueness
    visible_part_opts = ["Plot", "Series", "Axis", "Legend", "##", ""]
    visible = rng.choice(visible_part_opts)
    if visible == "":
        visible = _rand_visible_string(rng, rng.randint(0, 6))
    # Ensure there is an ID after ## even if visible already contains ##
    suffix = ''.join(rng.choice(string.ascii_letters + string.digits) for _ in range(rng.randint(1, 12)))
    return f"{visible}##{suffix}"

def _long_title(rng: random.Random, target_len: int) -> str:
    parts: List[str] = []
    while sum(len(p) for p in parts) < target_len:
        choice = rng.random()
        if choice < 0.25:
            parts.append(_hidden_label(rng))
        elif choice < 0.5:
            parts.append(_rand_visible_string(rng, rng.randint(5, 20)))
        elif choice < 0.75:
            parts.append(str(rng.uniform(-1e6, 1e6)))
        else:
            parts.append(rng.choice(["/", "_", "-", ":", " | "]))
    s = ' '.join(parts)
    # Trim to requested size
    return s[:target_len]

def _numeric_like(rng: random.Random) -> str:
    # Useful for tick labels
    styles = [
        lambda: f"{rng.randint(-10**6, 10**6)}",
        lambda: f"{rng.uniform(-1e6, 1e6):.6g}",
        lambda: f"{rng.uniform(0, 1):.8f}",
        lambda: f"{rng.randint(0, 23)}:{rng.randint(0,59):02d}:{rng.randint(0,59):02d}",
        lambda: f"{rng.randint(1970, 2100)}-{rng.randint(1,12):02d}-{rng.randint(1,28):02d}",
        lambda: f"1e{rng.randint(-308, 308)}",
    ]
    return rng.choice(styles)()

def _unicode_mix(rng: random.Random, n: int) -> str:
    # Mixed ASCII and higher planes (incl. emoji)
    s = []
    for _ in range(n):
        if rng.random() < 0.2:
            # Insert combining sequences sometimes
            base = _rand_unicode_char(rng)
            s.append(base)
            for _ in range(rng.randint(1, 3)):
                s.append(chr(rng.randint(0x0300, 0x036F)))
        else:
            s.append(_rand_unicode_char(rng))
    return ''.join(s)

def _short_interesting(rng: random.Random) -> str:
    # Very short cases including empty, single chars, punctuation-only
    choices = [
        "", " ", "\t", "\n", "0", "-", "+", ".", "%%", "%g", "%f",
        "#", "##", "###", "[]", "{}", "()", "..", "--", "__",
    ]
    if rng.random() < 0.5:
        return rng.choice(choices)
    return _rand_visible_string(rng, rng.randint(1, 6))

def _compose_payload(rng: random.Random) -> str:
    # Build a payload that concatenates multiple strings separated by NULs occasionally.
    # In stubs, std::string.c_str() will stop at first NUL, but remaining bytes still
    # feed further FUZZ_PARAM_STR calls.
    segments: List[str] = []
    # Decide number of segments
    seg_count = rng.randint(3, 10)
    for i in range(seg_count):
        kind = rng.random()
        if kind < 0.15:
            segments.append(_short_interesting(rng))
        elif kind < 0.30:
            segments.append(_hidden_label(rng))
        elif kind < 0.45:
            segments.append(_numeric_like(rng))
        elif kind < 0.65:
            segments.append(_rand_visible_string(rng, rng.randint(5, 40)))
        elif kind < 0.85:
            segments.append(_unicode_mix(rng, rng.randint(4, 24)))
        else:
            segments.append(_long_title(rng, rng.randint(30, 120)))
    # Insert some separators that are common in titles/labels
    sep_choices = ["\0", "|", ": ", " / ", " - ", "\\", "; "]
    s = []
    for idx, seg in enumerate(segments):
        if idx:
            s.append(rng.choice(sep_choices))
        s.append(seg)
    composite = ''.join(s)
    # Ensure we include some labels that likely appear verbatim
    if rng.random() < 0.4:
        composite = "ImPlot Demo##id-" + str(rng.randint(0, 1_000_000)) + "\0" + composite
    if rng.random() < 0.3:
        composite += "\0Series##" + ''.join(rng.choice(string.hexdigits) for _ in range(8))
    return composite

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    payload = _compose_payload(rng)
    # Limit to 4096 bytes when encoded. If over, trim the Python string first by ratio.
    b = payload.encode('utf-8', errors='ignore')
    if len(b) > 4096:
        # Approximate trim by character length proportion
        keep = max(1, int(len(payload) * 4096 / (len(b) + 1)))
        b = payload[:keep].encode('utf-8', errors='ignore')
        if len(b) > 4096:
            b = b[:4096]
    return b
